// Company "paid / disbursed" stamp used to certify payroll receipts and
// timesheet printouts once a payment has actually been recorded.
// Stored as an inline data URI (not a /public path) because this asset is
// injected into standalone print windows created via window.open('', ...)
// + document.write(...) — those documents have no reliable relative/base
// URL back to this app's origin, so a network-independent data URI is the
// only rendering method guaranteed to work across browsers and offline.
export const PAID_STAMP_DATA_URI = 'data:image/png;base64,';
